test('one actual indexed shell is closed, consistently oriented, nondegenerate and positive-volume',()=>{const a=build(T),r=topology(a.body.geometry);assert.equal(r.boundaryEdges,0);assert.equal(r.nonmanifoldEdges,0);assert.equal(r.inconsistentEdges,0);assert.equal(r.invalidPositions,0);assert.equal(r.degenerateTriangles,0);assert.ok(r.signedVolume>.2);assert.equal(r.vertices,2576);assert.equal(r.triangles,5184);for(let i=0;i<a.body.geometry.attributes.normal.count;i++)near(new T.Vector3().fromBufferAttribute(a.body.geometry.attributes.normal,i).length(),1,1e-5);a.dispose();});
test('body/spout junction removes both actual wall patches and shares18vertex boundaries without cap faces',()=>{const a=build(T);assert.equal(a.metadata.removedBodyCellsEachWall,18);assert.equal(a.metadata.portOuterPoints.length,18);assert.equal(a.metadata.portInnerPoints.length,18);const positions=a.body.geometry.attributes.position;for(const p of[...a.metadata.portOuterPoints,...a.metadata.portInnerPoints]){let found=0;for(let i=0;i<positions.count;i++)if(new T.Vector3().fromBufferAttribute(positions,i).distanceTo(new T.Vector3(...p))<1e-6)found++;assert.equal(found,1);}assert.equal(actualHits(a,[0,.70,0],[-.77,.70,0]).length,0);assert.ok(actualHits(a,[0,.7,.2],[0,.7,.9]).length);a.dispose();});
