test('perforated rose has actual wall thickness with separated holes; held wall occupancy rejects false open controls',()=>{const a=build(T);assert.equal(a.metadata.roseTrueThroughHoles,9);assert.equal(a.metadata.roseThickness,.035);const centers=a.metadata.roseHoleCenters;for(let i=0;i<centers.length;i++)for(let j=i+1;j<centers.length;j++)assert.ok(new T.Vector3(...centers[i]).distanceTo(new T.Vector3(...centers[j]))>.046);const m=a.metadata,t=new T.Vector3(...m.roseAxis),u=new T.Vector3(0,0,1).addScaledVector(t,-t.z).normalize();for(const c of centers){const center=new T.Vector3(...c);assert.equal(actualHits(a,center.clone().addScaledVector(t,-.045).toArray(),center.clone().addScaledVector(t,.085).toArray()).length,0);assert.ok(actualHits(a,center.clone().addScaledVector(u,.032).addScaledVector(t,-.04).toArray(),center.clone().addScaledVector(u,.032).addScaledVector(t,.075).toArray()).length);}a.dispose();});
