test('current village five support rays,63 walkability samples and full road/card/building/shore rectangle clear',()=>{const f=fixture(),before=JSON.stringify(f.world),surfaces=f.model.surfaces.slice(),occluders=f.model.occluders.slice(),r=placeAndProbe(T,Scene,Town,f.world,f.model,f.item);assert.equal(r.supports.length,5);assert.equal(r.finiteWalkability.samples,63);assert.equal(r.finiteWalkability.blocked,0);for(const s of r.supports)near(s.soleMinusFloor,0);assert.ok(r.minimumRoadGap>=r.requiredMargin);assert.ok(r.originalSpriteEnvelopeClearance.minimumGap>=r.requiredMargin);assert.ok(r.originalSpriteEnvelopeClearance.checkedCards>0);assert.ok(r.roads.reduce((n,r)=>n+r.triangles,0)>0);assert.ok(r.shoreline.minimumGap>=r.requiredMargin);assert.equal(r.meadowClusters.siteCount,40);assert.ok(r.meadowClusters.minimumGap>=r.requiredMargin);assert.ok(r.buildingProxyClearance.every(x=>!x.intersects));assert.ok(r.waterBacking.soleAboveWaterBacking>0);assert.equal(JSON.stringify(f.world),before);assert.deepEqual(f.model.surfaces,surfaces);assert.deepEqual(f.model.occluders,occluders);assert.equal(r.notRegisteredAsTownSurface,true);assert.equal(r.bodyBinding,null);assert.deepEqual(f.item.group.scale.toArray(),[1,1,1]);f.dispose();});
