test('pinned original and current runtime inputs match SHA; no original bytes/game state/production save mutation',()=>{const m=JSON.parse(fs.readFileSync(path.join(base,'input-manifest.json')));assert.equal(m.unit_id,spec.unit);assert.equal(m.source_base,'633010a49deac4ca6c9305d0266f74f0d0e568c0');for(const r of m.inputs){const p=r.path.startsWith('/static/')?path.join(import.meta.dirname,'..',r.path.slice(1)):r.path.startsWith('./')?path.join(base,r.path):r.path;const data=fs.readFileSync(p);assert.equal(data.length,r.bytes);assert.equal(crypto.createHash('sha256').update(data).digest('hex'),r.sha256,r.path);}assert.equal(m.inputs[0].sha256,'09b7bc6adeb8ff993f9e00480b188c6450d6e125505ace75a0aab5228a52eed3');assert.equal(m.normal_game_change,false);assert.equal(m.bodyBinding,null);const s=JSON.parse(fs.readFileSync(path.join(base,'SPEC.json')));for(const k of['body_fit_verified','grip_carrying_pouring_verified','liquid_simulation','normal_game_integration','ownership_unlock_save'])assert.equal(s[k],false);});
